export const GOVERNED_OPENAPI_DOCUMENT: string = "{\n  \"openapi\": \"3.1.0\",\n  \"info\": {\n    \"title\": \"Alloy Public API\",\n    \"version\": \"1.0.0\",\n    \"x-spec-status\": \"public-v1\",\n    \"description\": \"The Alloy Public API. This artifact describes ONLY endpoints that exist. Coverage is a build gate, not a report: a documented path with no route, or a route under /api/v1 with no documentation, fails the drift guard in web/tests/platform/external/openApiDriftGuard.test.ts.\\n\\nAuthority is never chosen by the caller. An access token resolves to exactly one installation, and that installation determines the organization, the granted scopes and the resource boundary. There is no org_id parameter anywhere in this contract.\"\n  },\n  \"servers\": [\n    {\n      \"url\": \"https://{host}\",\n      \"variables\": {\n        \"host\": {\n          \"default\": \"app.alloy.example\"\n        }\n      }\n    }\n  ],\n  \"security\": [\n    {\n      \"bearerAuth\": []\n    }\n  ],\n  \"tags\": [\n    {\n      \"name\": \"Authentication\",\n      \"description\": \"Exchanging an installation credential for a short-lived access token.\"\n    },\n    {\n      \"name\": \"Context\",\n      \"description\": \"The caller's own installation context.\"\n    },\n    {\n      \"name\": \"Locations\",\n      \"description\": \"Organizational locations — sites and the units within them.\"\n    }\n  ],\n  \"paths\": {\n    \"/api/v1/oauth/token\": {\n      \"post\": {\n        \"operationId\": \"issueAccessToken\",\n        \"tags\": [\n          \"Authentication\"\n        ],\n        \"summary\": \"Exchange an installation credential for an access token\",\n        \"description\": \"Client-credentials grant. The returned token is opaque, expires in 15 minutes, and carries no authority of its own — scopes and resource boundary are re-read from the installation on every request, so a revocation takes effect on the next call.\",\n        \"security\": [],\n        \"requestBody\": {\n          \"required\": true,\n          \"content\": {\n            \"application/json\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/TokenRequest\"\n              }\n            },\n            \"application/x-www-form-urlencoded\": {\n              \"schema\": {\n                \"$ref\": \"#/components/schemas/TokenRequest\"\n              }\n            }\n          }\n        },\n        \"responses\": {\n          \"200\": {\n            \"description\": \"An access token.\",\n            \"headers\": {\n              \"X-Request-Id\": {\n                \"$ref\": \"#/components/headers/RequestId\"\n              },\n              \"RateLimit-Limit\": {\n                \"$ref\": \"#/components/headers/RateLimitLimit\"\n              },\n              \"RateLimit-Remaining\": {\n                \"$ref\": \"#/components/headers/RateLimitRemaining\"\n              },\n              \"RateLimit-Reset\": {\n                \"$ref\": \"#/components/headers/RateLimitReset\"\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/TokenResponse\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/InvalidRequest\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/InvalidCredential\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/RateLimited\"\n          },\n          \"500\": {\n            \"$ref\": \"#/components/responses/InternalError\"\n          }\n        }\n      }\n    },\n    \"/api/v1/context\": {\n      \"get\": {\n        \"operationId\": \"getContext\",\n        \"tags\": [\n          \"Context\"\n        ],\n        \"summary\": \"Describe the calling installation\",\n        \"description\": \"Returns the caller's own application, installation, organization, granted scopes and resource boundary. Touches no domain data. This is the correct first call for any integration: it answers which tenant you are and what you may do, before anything depends on the answer.\",\n        \"responses\": {\n          \"200\": {\n            \"description\": \"The caller's installation context.\",\n            \"headers\": {\n              \"X-Request-Id\": {\n                \"$ref\": \"#/components/headers/RequestId\"\n              },\n              \"RateLimit-Limit\": {\n                \"$ref\": \"#/components/headers/RateLimitLimit\"\n              },\n              \"RateLimit-Remaining\": {\n                \"$ref\": \"#/components/headers/RateLimitRemaining\"\n              },\n              \"RateLimit-Reset\": {\n                \"$ref\": \"#/components/headers/RateLimitReset\"\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/Context\"\n                }\n              }\n            }\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/InvalidCredential\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/RateLimited\"\n          },\n          \"500\": {\n            \"$ref\": \"#/components/responses/InternalError\"\n          }\n        }\n      }\n    },\n    \"/api/v1/locations\": {\n      \"get\": {\n        \"operationId\": \"listLocations\",\n        \"tags\": [\n          \"Locations\"\n        ],\n        \"summary\": \"List organizational locations\",\n        \"description\": \"Returns sites and units within the installation's organization AND its resource boundary. Requires the `locations.read` scope.\\n\\nCustomer and vendor premises (`location_type = address`) are never returned at any scope — they describe private addresses rather than organizational locations.\\n\\nFilters narrow the already-authorized set and can never widen it: naming a location outside the boundary returns nothing rather than granting it.\\n\\nIncremental sync: page the collection once, remember the newest `updated_at` you saw, then pass it as `updated_since`. Rewind your checkpoint slightly — `updated_at` is wall-clock and not transactionally ordered.\",\n        \"security\": [\n          {\n            \"bearerAuth\": []\n          }\n        ],\n        \"x-required-scope\": \"locations.read\",\n        \"parameters\": [\n          {\n            \"name\": \"limit\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 200,\n              \"default\": 50\n            },\n            \"description\": \"Page size. Clamped to 200.\"\n          },\n          {\n            \"name\": \"cursor\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Opaque cursor from a previous `next_cursor`. A cursor is a position, never a permission.\"\n          },\n          {\n            \"name\": \"since_token\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Resume exactly where a previous pass stopped. Pass back the `sync_token` from the last page you consumed. Unlike `updated_since` it identifies a single row, so two records sharing a timestamp cannot be skipped or repeated. Prefer this for incremental synchronization.\"\n          },\n          {\n            \"name\": \"type\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\",\n              \"enum\": [\n                \"site\",\n                \"unit\"\n              ]\n            }\n          },\n          {\n            \"name\": \"parent_id\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Return only direct children of this location.\"\n          },\n          {\n            \"name\": \"location_id\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Return only this location, if it is within the boundary. Use this for a single-resource read.\"\n          },\n          {\n            \"name\": \"updated_since\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\",\n              \"format\": \"date-time\"\n            },\n            \"description\": \"Return only records changed strictly after this instant. Must carry a timezone offset or Z. Sub-second precision is honoured exactly as supplied. `since_token` is preferred: a timestamp alone cannot separate two records that share one.\"\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"A page of locations.\",\n            \"headers\": {\n              \"X-Request-Id\": {\n                \"$ref\": \"#/components/headers/RequestId\"\n              },\n              \"RateLimit-Limit\": {\n                \"$ref\": \"#/components/headers/RateLimitLimit\"\n              },\n              \"RateLimit-Remaining\": {\n                \"$ref\": \"#/components/headers/RateLimitRemaining\"\n              },\n              \"RateLimit-Reset\": {\n                \"$ref\": \"#/components/headers/RateLimitReset\"\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/LocationPage\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/InvalidRequest\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/InvalidCredential\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/ForbiddenScope\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/RateLimited\"\n          },\n          \"500\": {\n            \"$ref\": \"#/components/responses/InternalError\"\n          }\n        }\n      }\n    },\n    \"/api/v1/attendance-events\": {\n      \"get\": {\n        \"operationId\": \"listAttendanceEvents\",\n        \"tags\": [\n          \"Locations\"\n        ],\n        \"summary\": \"List canonical attendance facts\",\n        \"description\": \"Append-only attendance facts for children at sites within this installation's location boundary.\\n\\nNothing in this collection is ever removed or rewritten. A mistake is corrected by a later fact whose `entry_type` is `correction` (it restates) or `reversal` (it voids), and which names the fact it supersedes in `corrects_event_id`. Fold them the way Alloy does: a superseded fact is no longer effective, and a reversal leaves nothing behind but its own record. Because nothing disappears, a consumer that has read every page holds the complete history.\\n\\nOrder and synchronization both advance on `recorded_at` — when Alloy recorded the fact — not on `event_at`. A correction to last week is recorded today and therefore arrives today; ordering by when things happened would file it behind a checkpoint you had already passed.\\n\\n## Keeping a copy in step\\n\\n1. Bootstrap: request without `since_token` or `updated_since`.\\n2. Follow `next_cursor` until it is null, storing each page as you go.\\n3. When the pass completes, persist the `sync_token` from the last page you consumed. Persist it only after the whole pass succeeded — a token saved mid-pass would skip whatever you did not store.\\n4. Next time, request with `since_token` set to the value you persisted.\\n5. Follow `next_cursor` to exhaustion again, then persist the new `sync_token`.\\n\\nA `sync_token` identifies one record, not an instant, so records sharing a timestamp are neither skipped nor repeated. If you checkpoint with `updated_since` instead, supply the exact `recorded_at` you stopped at — it is matched at full precision.\\n\\n### Example\\n\\nBootstrap, then resume:\\n\\n```\\nGET /api/v1/attendance-events?limit=200\\n  -> { \\\"data\\\": [...], \\\"next_cursor\\\": \\\"eyJ...\\\", \\\"sync_token\\\": \\\"eyJ...\\\" }\\nGET /api/v1/attendance-events?limit=200&cursor=eyJ...\\n  -> { \\\"data\\\": [...], \\\"next_cursor\\\": null, \\\"sync_token\\\": \\\"eyJhZ...\\\" }\\n\\n# store \\\"eyJhZ...\\\", then later:\\nGET /api/v1/attendance-events?limit=200&since_token=eyJhZ...\\n  -> only facts recorded after the one that token names\\n```\\n\\nNarrow a sync to one site or one child with `site_id` or `child_id`; filters never widen what your installation may read.\",\n        \"security\": [\n          {\n            \"bearerAuth\": []\n          }\n        ],\n        \"x-required-scope\": \"attendance.read\",\n        \"parameters\": [\n          {\n            \"name\": \"limit\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"integer\",\n              \"minimum\": 1,\n              \"maximum\": 200,\n              \"default\": 50\n            },\n            \"description\": \"Page size. Clamped to 200.\"\n          },\n          {\n            \"name\": \"cursor\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Opaque cursor from a previous `next_cursor`. A cursor is a position, never a permission.\"\n          },\n          {\n            \"name\": \"since_token\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Resume exactly where a previous pass stopped. Pass back the `sync_token` from the last page you consumed. Unlike `updated_since` it identifies a single row, so two records sharing a timestamp cannot be skipped or repeated. Prefer this for incremental synchronization.\"\n          },\n          {\n            \"name\": \"updated_since\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\",\n              \"format\": \"date-time\"\n            },\n            \"description\": \"Return only records changed strictly after this instant. Must carry a timezone offset or Z. Sub-second precision is honoured exactly as supplied. `since_token` is preferred: a timestamp alone cannot separate two records that share one.\"\n          },\n          {\n            \"name\": \"site_id\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Narrow to one site. A site outside your boundary narrows to nothing rather than widening to it.\"\n          },\n          {\n            \"name\": \"child_id\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\"\n            },\n            \"description\": \"Narrow to one child.\"\n          },\n          {\n            \"name\": \"event_kind\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\",\n              \"enum\": [\n                \"check_in\",\n                \"check_out\",\n                \"absence\",\n                \"present\",\n                \"room_transfer\",\n                \"schedule_override\"\n              ]\n            },\n            \"description\": \"Narrow to one kind of fact.\"\n          },\n          {\n            \"name\": \"service_date_from\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\",\n              \"format\": \"date\"\n            },\n            \"description\": \"Narrow to facts on or after this service day.\"\n          },\n          {\n            \"name\": \"service_date_to\",\n            \"in\": \"query\",\n            \"required\": false,\n            \"schema\": {\n              \"type\": \"string\",\n              \"format\": \"date\"\n            },\n            \"description\": \"Narrow to facts on or before this service day.\"\n          }\n        ],\n        \"responses\": {\n          \"200\": {\n            \"description\": \"A page of attendance facts.\",\n            \"headers\": {\n              \"X-Request-Id\": {\n                \"$ref\": \"#/components/headers/RequestId\"\n              },\n              \"RateLimit-Limit\": {\n                \"$ref\": \"#/components/headers/RateLimitLimit\"\n              },\n              \"RateLimit-Remaining\": {\n                \"$ref\": \"#/components/headers/RateLimitRemaining\"\n              },\n              \"RateLimit-Reset\": {\n                \"$ref\": \"#/components/headers/RateLimitReset\"\n              }\n            },\n            \"content\": {\n              \"application/json\": {\n                \"schema\": {\n                  \"$ref\": \"#/components/schemas/AttendanceEventPage\"\n                }\n              }\n            }\n          },\n          \"400\": {\n            \"$ref\": \"#/components/responses/InvalidRequest\"\n          },\n          \"401\": {\n            \"$ref\": \"#/components/responses/InvalidCredential\"\n          },\n          \"403\": {\n            \"$ref\": \"#/components/responses/ForbiddenScope\"\n          },\n          \"429\": {\n            \"$ref\": \"#/components/responses/RateLimited\"\n          },\n          \"500\": {\n            \"$ref\": \"#/components/responses/InternalError\"\n          }\n        }\n      }\n    }\n  },\n  \"components\": {\n    \"securitySchemes\": {\n      \"bearerAuth\": {\n        \"type\": \"http\",\n        \"scheme\": \"bearer\",\n        \"description\": \"An opaque access token from /api/v1/oauth/token. Not a JWT; do not parse it.\"\n      }\n    },\n    \"headers\": {\n      \"RequestId\": {\n        \"description\": \"Server-generated identifier for this request. Quote it to support. Present on every response.\",\n        \"schema\": {\n          \"type\": \"string\"\n        }\n      },\n      \"RateLimitLimit\": {\n        \"description\": \"Requests permitted in the current window.\",\n        \"schema\": {\n          \"type\": \"integer\"\n        }\n      },\n      \"RateLimitRemaining\": {\n        \"description\": \"Requests remaining in the current window.\",\n        \"schema\": {\n          \"type\": \"integer\"\n        }\n      },\n      \"RateLimitReset\": {\n        \"description\": \"Seconds until the window resets.\",\n        \"schema\": {\n          \"type\": \"integer\"\n        }\n      }\n    },\n    \"schemas\": {\n      \"TokenRequest\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"grant_type\",\n          \"client_id\",\n          \"client_secret\"\n        ],\n        \"properties\": {\n          \"grant_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"client_credentials\"\n            ]\n          },\n          \"client_id\": {\n            \"type\": \"string\",\n            \"description\": \"Public, non-secret credential identifier.\"\n          },\n          \"client_secret\": {\n            \"type\": \"string\",\n            \"description\": \"Shown once at creation and never retrievable afterwards.\"\n          }\n        }\n      },\n      \"TokenResponse\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"access_token\",\n          \"token_type\",\n          \"expires_in\"\n        ],\n        \"properties\": {\n          \"access_token\": {\n            \"type\": \"string\",\n            \"description\": \"Opaque. Do not parse.\"\n          },\n          \"token_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"Bearer\"\n            ]\n          },\n          \"expires_in\": {\n            \"type\": \"integer\",\n            \"description\": \"Seconds until expiry.\"\n          },\n          \"scope\": {\n            \"type\": \"string\",\n            \"description\": \"Space-delimited scopes the installation currently grants. Informational — authority is re-read from the installation on every request, not carried by the token.\"\n          }\n        }\n      },\n      \"Context\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"application\",\n          \"installation\",\n          \"organization\",\n          \"scopes\",\n          \"resource_boundary\"\n        ],\n        \"properties\": {\n          \"application\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"id\": {\n                \"type\": \"string\"\n              },\n              \"slug\": {\n                \"type\": \"string\"\n              },\n              \"environment\": {\n                \"type\": \"string\",\n                \"enum\": [\n                  \"sandbox\",\n                  \"production\"\n                ]\n              }\n            }\n          },\n          \"installation\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"id\": {\n                \"type\": \"string\"\n              },\n              \"status\": {\n                \"type\": \"string\",\n                \"enum\": [\n                  \"active\"\n                ]\n              }\n            }\n          },\n          \"organization\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"id\": {\n                \"type\": \"string\"\n              }\n            }\n          },\n          \"scopes\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"type\": \"string\"\n            }\n          },\n          \"resource_boundary\": {\n            \"oneOf\": [\n              {\n                \"type\": \"object\",\n                \"required\": [\n                  \"mode\"\n                ],\n                \"properties\": {\n                  \"mode\": {\n                    \"type\": \"string\",\n                    \"enum\": [\n                      \"org_wide\"\n                    ]\n                  }\n                }\n              },\n              {\n                \"type\": \"object\",\n                \"required\": [\n                  \"mode\",\n                  \"location_ids\"\n                ],\n                \"properties\": {\n                  \"mode\": {\n                    \"type\": \"string\",\n                    \"enum\": [\n                      \"locations\"\n                    ]\n                  },\n                  \"location_ids\": {\n                    \"type\": \"array\",\n                    \"items\": {\n                      \"type\": \"string\"\n                    },\n                    \"description\": \"An EMPTY list denies everything. It never means all locations.\"\n                  }\n                }\n              }\n            ]\n          }\n        }\n      },\n      \"Error\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"error\"\n        ],\n        \"properties\": {\n          \"error\": {\n            \"type\": \"object\",\n            \"required\": [\n              \"code\",\n              \"type\",\n              \"message\",\n              \"request_id\"\n            ],\n            \"properties\": {\n              \"code\": {\n                \"type\": \"string\",\n                \"description\": \"Stable and machine-readable. Branch on this.\"\n              },\n              \"type\": {\n                \"type\": \"string\",\n                \"enum\": [\n                  \"invalid_request\",\n                  \"unauthenticated\",\n                  \"forbidden_scope\",\n                  \"forbidden_resource\",\n                  \"not_found\",\n                  \"conflict\",\n                  \"rate_limited\",\n                  \"internal_error\"\n                ]\n              },\n              \"message\": {\n                \"type\": \"string\",\n                \"description\": \"For humans. NOT a contract; it may change.\"\n              },\n              \"request_id\": {\n                \"type\": \"string\"\n              },\n              \"details\": {\n                \"type\": \"object\",\n                \"additionalProperties\": true\n              }\n            }\n          }\n        }\n      },\n      \"Location\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"id\",\n          \"type\",\n          \"name\",\n          \"parent_id\",\n          \"site_id\",\n          \"active\",\n          \"updated_at\"\n        ],\n        \"description\": \"A canonical Alloy location. `id` is Alloy's canonical identity; correlate your own identifiers separately rather than expecting Alloy to carry them.\",\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"description\": \"Canonical Alloy identifier. Opaque — do not parse.\"\n          },\n          \"type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"site\",\n              \"unit\"\n            ]\n          },\n          \"unit_role\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"enum\": [\n              \"physical_space\",\n              \"operational_group\",\n              \"shared_space\",\n              null\n            ],\n            \"description\": \"Topology role, units only. Null means unknown — it was never back-filled to a guess.\"\n          },\n          \"name\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ]\n          },\n          \"parent_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Structural parent.\"\n          },\n          \"site_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"The site this location sits under, resolved by Alloy's site-resolution authority. Null for an orphan.\"\n          },\n          \"active\": {\n            \"type\": \"boolean\"\n          },\n          \"updated_at\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\",\n            \"description\": \"Resync watermark. Re-request from slightly BEFORE your last value and upsert — it is wall-clock and not transactionally ordered.\"\n          }\n        }\n      },\n      \"LocationPage\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"data\",\n          \"next_cursor\",\n          \"sync_token\"\n        ],\n        \"properties\": {\n          \"data\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"$ref\": \"#/components/schemas/Location\"\n            }\n          },\n          \"next_cursor\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Pass back as `cursor`. Null means the last page — you never need a request to discover there is nothing left.\"\n          },\n          \"sync_token\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Exact position of the last record on this page. Persist it after a successful pass and pass it back as `since_token` to resume. Returned on every page that has records, including the last one.\"\n          }\n        }\n      },\n      \"AttendanceEvent\": {\n        \"type\": \"object\",\n        \"description\": \"One canonical attendance fact. Append-only: a mistake is corrected by a later event that names this one, never by changing it.\",\n        \"required\": [\n          \"id\",\n          \"child_id\",\n          \"site_id\",\n          \"event_kind\",\n          \"entry_type\",\n          \"event_at\",\n          \"service_date\",\n          \"actor_type\",\n          \"source\",\n          \"recorded_at\"\n        ],\n        \"properties\": {\n          \"id\": {\n            \"type\": \"string\",\n            \"description\": \"Stable identifier for this attendance fact.\"\n          },\n          \"child_id\": {\n            \"type\": \"string\",\n            \"description\": \"The Alloy identifier of the child this fact is about.\"\n          },\n          \"child_external_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Your own identifier for this child, as your installation has mapped it. Null when you have not mapped one. It is the identifier you supplied for the child, returned so you can match this fact to your own record without keeping a second lookup table.\"\n          },\n          \"site_id\": {\n            \"type\": \"string\",\n            \"description\": \"The site the fact was recorded at. Always within your installation's location boundary.\"\n          },\n          \"room_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"The room the fact happened in, for facts that name one. A room is a location of type `unit`; the same identifier appears in GET /api/v1/locations.\"\n          },\n          \"from_room_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"The room a child moved out of. Present only on a `room_transfer`.\"\n          },\n          \"to_room_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"The room a child moved into. Present only on a `room_transfer`.\"\n          },\n          \"event_kind\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"check_in\",\n              \"check_out\",\n              \"absence\",\n              \"present\",\n              \"room_transfer\",\n              \"schedule_override\"\n            ],\n            \"description\": \"What happened: `check_in` and `check_out` are arrival and departure, `room_transfer` is a move between rooms, `absence` records an expected child who did not attend, `present` is an observed presence without a recorded arrival, and `schedule_override` records an operational change to the day itself.\"\n          },\n          \"entry_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"original\",\n              \"correction\",\n              \"reversal\"\n            ],\n            \"description\": \"Whether this fact stands alone or acts on an earlier one. `original` is a first statement. `correction` restates a fact that was wrong, and the restated values are on the correction. `reversal` voids a fact that should not have been recorded and asserts nothing in its place. Both name their target in `corrects_event_id`.\"\n          },\n          \"corrects_event_id\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"The attendance fact this one supersedes, for corrections and reversals.\"\n          },\n          \"event_at\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\",\n            \"description\": \"When it physically happened.\"\n          },\n          \"service_date\": {\n            \"type\": \"string\",\n            \"format\": \"date\",\n            \"description\": \"The operating day this fact belongs to, in the organization's configured operational timezone. It is determined when the fact is recorded and is never recomputed afterwards. It is NOT the UTC date of `event_at`: a late-evening arrival and an early-morning one can share an operating day while falling on different UTC dates, and the reverse.\"\n          },\n          \"actor_type\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"staff\",\n              \"parent\",\n              \"guardian\",\n              \"emergency_contact\",\n              \"system\"\n            ],\n            \"description\": \"The kind of actor the fact was recorded by — a staff member, a parent, a guardian, an emergency contact, or an automated system. Alloy never identifies the individual here.\"\n          },\n          \"source\": {\n            \"type\": \"string\",\n            \"enum\": [\n              \"operator_action\",\n              \"staff_workspace\",\n              \"parent_portal\",\n              \"processing_import\",\n              \"system\",\n              \"kiosk\",\n              \"integration_api\",\n              \"door_access\",\n              \"mobile_app\"\n            ],\n            \"description\": \"The channel the fact was captured through. `integration_api` means it arrived through this API; `kiosk`, `staff_workspace`, `parent_portal` and `door_access` are the operational channels Alloy itself records through. Useful for telling your own writes apart from everyone else's.\"\n          },\n          \"recorded_at\": {\n            \"type\": \"string\",\n            \"format\": \"date-time\",\n            \"description\": \"When Alloy recorded it. This is the field incremental synchronization advances on, and the order the collection returns.\"\n          }\n        }\n      },\n      \"AttendanceEventPage\": {\n        \"type\": \"object\",\n        \"required\": [\n          \"data\",\n          \"next_cursor\",\n          \"sync_token\"\n        ],\n        \"properties\": {\n          \"data\": {\n            \"type\": \"array\",\n            \"items\": {\n              \"$ref\": \"#/components/schemas/AttendanceEvent\"\n            }\n          },\n          \"next_cursor\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Opaque cursor for the next page, or null when this is the last page.\"\n          },\n          \"sync_token\": {\n            \"type\": [\n              \"string\",\n              \"null\"\n            ],\n            \"description\": \"Exact position of the last record on this page. Persist it after a successful pass and pass it back as `since_token` to resume. Returned on every page that has records, including the last one.\"\n          }\n        }\n      }\n    },\n    \"responses\": {\n      \"InvalidRequest\": {\n        \"description\": \"The request contains an invalid or unsupported parameter, filter, cursor, sync token, or date value.\",\n        \"content\": {\n          \"application/json\": {\n            \"schema\": {\n              \"$ref\": \"#/components/schemas/Error\"\n            }\n          }\n        }\n      },\n      \"InvalidCredential\": {\n        \"description\": \"Authentication failed. Present valid credentials or obtain a new access token, then retry.\",\n        \"content\": {\n          \"application/json\": {\n            \"schema\": {\n              \"$ref\": \"#/components/schemas/Error\"\n            }\n          }\n        }\n      },\n      \"RateLimited\": {\n        \"description\": \"Rate limited. Honour Retry-After.\",\n        \"headers\": {\n          \"Retry-After\": {\n            \"description\": \"Seconds to wait.\",\n            \"schema\": {\n              \"type\": \"integer\"\n            }\n          }\n        },\n        \"content\": {\n          \"application/json\": {\n            \"schema\": {\n              \"$ref\": \"#/components/schemas/Error\"\n            }\n          }\n        }\n      },\n      \"InternalError\": {\n        \"description\": \"An unexpected failure. Carries a request_id and nothing else.\",\n        \"content\": {\n          \"application/json\": {\n            \"schema\": {\n              \"$ref\": \"#/components/schemas/Error\"\n            }\n          }\n        }\n      },\n      \"ForbiddenScope\": {\n        \"description\": \"The installation has not been granted the scope this operation requires.\",\n        \"content\": {\n          \"application/json\": {\n            \"schema\": {\n              \"$ref\": \"#/components/schemas/Error\"\n            }\n          }\n        }\n      }\n    }\n  }\n}\n";
